package com.jnapanam.sportszone.release1.controller;
import com.jnapanam.sportszone.booking.dto.*;import com.jnapanam.sportszone.booking.service.BookingService;import com.jnapanam.sportszone.payment.service.PaymentService;import com.jnapanam.sportszone.notification.service.NotificationService;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/frontdesk")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public class FrontDeskController{
 private final BookingService bookings;private final JdbcTemplate jdbc;private final NotificationService notifications;private final PaymentService payments;public FrontDeskController(BookingService b,JdbcTemplate j,NotificationService n,PaymentService p){bookings=b;jdbc=j;notifications=n;payments=p;}
 @PostMapping("/walk-in")public BookingResponse walkIn(@RequestBody Map<String,Object>b){UUID customer=UUID.fromString(b.get("customerUserId").toString());UUID slot=UUID.fromString(b.get("slotId").toString());int qty=Integer.parseInt(String.valueOf(b.getOrDefault("quantity",1)));HoldResponse h=bookings.hold(customer,new HoldRequest(slot,qty));return bookings.confirm(customer,new ConfirmRequest(h.id(),com.jnapanam.sportszone.booking.model.PaymentOption.PAY_AT_VENUE));}
 @PostMapping("/facilities/{facilityId}/emergency-close")public Map<String,Object> close(Authentication a,@PathVariable UUID facilityId,@RequestBody Map<String,Object>b){LocalDate date=LocalDate.parse(b.get("date").toString());String reason=String.valueOf(b.getOrDefault("reason","Emergency facility closure"));List<Map<String,Object>> affected=jdbc.queryForList("select b.id,b.user_id from bookings b join booking_slots s on s.id=b.slot_id where s.facility_id=? and s.slot_date=? and b.status in ('CONFIRMED','PENDING_PAYMENT')",facilityId,date);int cancelled=0;for(Map<String,Object>x:affected){UUID bid=(UUID)x.get("id"),uid=(UUID)x.get("user_id");try{bookings.adminCancel(bid,reason);try{payments.cancelBookingAndRefund(bid,reason);}catch(Exception ignored){}notifications.notify(uid,"FACILITY_CHANGE","Facility closure affects your booking",reason+". Your booking was cancelled; any eligible paid amount is being refunded. You may select another available slot.");cancelled++;}catch(Exception ignored){}}jdbc.update("insert into facility_emergency_actions(id,facility_id,closure_date,reason,action,affected_bookings,created_by) values(?,?,?,?,?,?,?)",UUID.randomUUID(),facilityId,date,reason,"CANCEL_NOTIFY",cancelled,UUID.fromString(a.getName()));return Map.of("affectedBookings",affected.size(),"cancelledAndNotified",cancelled,"date",date,"reason",reason);}
}
